using System.Collections;
using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

public class CorruptedAnimalActivation : UnitsDiceActivation
{
	[Header("Effects")]
	[SerializeField]
	private CorruptedAnimalEffectsList corruptedAnimalEffectsList;

	[Header("Components")]
	[SerializeField]
	private CorruptedAnimalSpriteControl corruptedAnimalSpriteControl;

	[SerializeField]
	private CorruptedAnimalEffects corruptedAnimalEffects;

	[SerializeField]
	private CorruptionStats corruptionStats;

	[SerializeField]
	private UnitDialogue unitDialogue;

	private CorruptedAnimalData corruptedAnimalData;

	public void InitializeCorruptedAnimalData(CorruptedAnimalData corruptedAnimalData)
	{
		this.corruptedAnimalData = corruptedAnimalData;
	}

	protected override Vector3 GetDiceHeightAdjustment()
	{
		if (corruptedAnimalData.EnableUnitsMiscData && corruptedAnimalData.UnitsMiscData.EnableDiceHeightAdjustment)
		{
			return Vector3.up * corruptedAnimalData.UnitsMiscData.DiceHeightAdjustment;
		}
		return Vector3.zero;
	}

	public override int GetDiceAmount()
	{
		if (!corruptedAnimalEffects.IsEffectActive(corruptedAnimalEffectsList.HatchingChrysalisEffect) && !corruptedAnimalEffects.IsEffectActive(corruptedAnimalEffectsList.CollapsedSunEffect))
		{
			if (!boosted)
			{
				return 1;
			}
			return 2;
		}
		return 0;
	}

	public override List<DiceInstance> GetDiceInstancesToRoll(bool ignoreDisabledActions = false)
	{
		List<DiceInstance> result = new List<DiceInstance>();
		if (corruptedAnimalEffects.IsEffectActive(corruptedAnimalEffectsList.HatchingChrysalisEffect, activateFeedback: false) || corruptedAnimalEffects.IsEffectActive(corruptedAnimalEffectsList.CollapsedSunEffect, activateFeedback: false))
		{
			return result;
		}
		return base.GetDiceInstancesToRoll();
	}

	public void HideDiceFace(bool hideDiceFace)
	{
		base.hideDiceFace = hideDiceFace;
		if (BasicDiceSpawned)
		{
			basicDiceInstance.ToggleHideDiceFace(hideDiceFace);
			if (boosted && BoostDiceSpawned)
			{
				boostDiceInstance.ToggleHideDiceFace(hideDiceFace);
			}
		}
	}

	public IEnumerator StartTurnActivation()
	{
		if ((base.gameObject.activeInHierarchy && BasicDiceSpawned) || CheckHasHatchingChrysalisEffect() || CheckHasCollapsedSunEffect())
		{
			if (hideDiceFace)
			{
				float num = corruptedAnimalEffects.IsHiddenActiveDecreaseAndLeaveHiddenAnimation();
				HideDiceFace(hideDiceFace: false);
				yield return new WaitForSeconds((num <= 0f) ? 0.6f : num);
			}
			corruptedAnimalEffects.OnStartTurnEffects();
			corruptedAnimalEffects.OnStartTurnDecreaseEffects();
		}
	}

	private bool CheckHasHatchingChrysalisEffect()
	{
		return corruptedAnimalEffects.IsEffectActive(corruptedAnimalEffectsList.HatchingChrysalisEffect, activateFeedback: false);
	}

	private bool CheckHasCollapsedSunEffect()
	{
		return corruptedAnimalEffects.IsEffectActive(corruptedAnimalEffectsList.CollapsedSunEffect, activateFeedback: false);
	}

	public IEnumerator BasicDiceActivation(AnimationType animationType = AnimationType.Attack)
	{
		if (base.gameObject.activeInHierarchy && corruptionStats.CurrentCorruption > 0f && !corruptedAnimalEffects.IsEffectActive(corruptedAnimalEffectsList.HatchingChrysalisEffect, activateFeedback: false) && !corruptedAnimalEffects.IsEffectActive(corruptedAnimalEffectsList.CollapsedSunEffect, activateFeedback: false) && BasicDiceSpawned && !corruptedAnimalEffects.IsEffectActiveWithActivation(corruptedAnimalEffectsList.FreezeEnemyEffect))
		{
			if (unitDialogue.HasDialogueTypeShowDialogueBoxRandomDialogue(DialogueTypeEnum.ACTIVATION))
			{
				yield return new WaitForSeconds(2.5f);
			}
			else
			{
				yield return new WaitForSeconds(0.1f);
			}
			yield return ActivateDice(basicDiceInstance.ActionFace as DiceFace, animationType);
			yield return new WaitForSeconds(0.1f);
		}
	}

	public IEnumerator BoostDiceActivation(AnimationType animationType = AnimationType.Attack)
	{
		if (base.gameObject.activeInHierarchy && !corruptedAnimalEffects.IsEffectActive(corruptedAnimalEffectsList.HatchingChrysalisEffect, activateFeedback: false) && !corruptedAnimalEffects.IsEffectActive(corruptedAnimalEffectsList.CollapsedSunEffect, activateFeedback: false) && BoostDiceSpawned && boosted && !corruptedAnimalEffects.IsEffectActiveWithActivation(corruptedAnimalEffectsList.FreezeEnemyEffect))
		{
			if (unitDialogue.HasDialogueTypeShowDialogueBoxRandomDialogue(DialogueTypeEnum.ACTIVATION))
			{
				yield return new WaitForSeconds(2.5f);
			}
			else
			{
				yield return new WaitForSeconds(0.1f);
			}
			if (base.gameObject.activeInHierarchy && corruptionStats.CurrentCorruption > 0f)
			{
				yield return ActivateDice(boostDiceInstance.ActionFace as DiceFace, animationType);
				yield return new WaitForSeconds(0.1f);
			}
		}
	}

	private IEnumerator ActivateDice(DiceFace rolledDiceFace, AnimationType animationType)
	{
		yield return StartCoroutine(corruptedAnimalSpriteControl.PlayAttackAnimation(animationType, delegate
		{
			ExecuteDiceEffect(rolledDiceFace);
		}));
	}

	private void ExecuteDiceEffect(DiceFace rolledDiceFace)
	{
		if (rolledDiceFace.BattleAction.EnableEnemyLogics)
		{
			rolledDiceFace.BattleAction.enemyActionLogic.ActivateAction(rolledDiceFace.BattleAction, rolledDiceFace.ModifiedActionValue, base.gameObject);
			if (rolledDiceFace.EnableSecondAction && rolledDiceFace.SecondBattleAction.EnableEnemyLogics)
			{
				rolledDiceFace.SecondBattleAction.enemyActionLogic.ActivateAction(rolledDiceFace.SecondBattleAction, rolledDiceFace.SecondModifiedActionValue, base.gameObject);
			}
		}
		else
		{
			Debug.Log("No enemyActionLogic on this battle action");
		}
	}

	public IEnumerator EndOfTurnActivation()
	{
		if (((base.gameObject.activeInHierarchy && corruptionStats.CurrentCorruption > 0f && BasicDiceSpawned) || CheckHasHatchingChrysalisEffect() || CheckHasCollapsedSunEffect()) && corruptedAnimalEffects.OnEndTurnEffects())
		{
			yield return new WaitForSeconds(0.3f);
		}
	}

	public IEnumerator EndOfTurnResetActivation()
	{
		yield return InvokeAlternatives.WaitOneFrame();
		if (corruptionStats.CurrentCorruption > 0f && BasicDiceSpawned)
		{
			ResetDice(ref basicDice, basicDiceInstance);
			if (boosted && BoostDiceSpawned)
			{
				ResetDice(ref boostDice, boostDiceInstance);
			}
			yield return InvokeAlternatives.WaitOneFrame();
			corruptedAnimalEffects.OnEndTurnDecreaseEffects();
		}
		else if (CheckHasHatchingChrysalisEffect() || CheckHasCollapsedSunEffect())
		{
			yield return InvokeAlternatives.WaitOneFrame();
			corruptedAnimalEffects.OnEndTurnDecreaseEffects();
		}
	}
}
